"""Actual continuation, private setup restoration, and subdistribution distance."""
BASE='ntruplus/proof/768/ref/kem_cca_setup/'
GAME=BASE+'NTRUPlus768CCASetupGame.ec'
DIST=BASE+'NTRUPlus768CCASetupDistribution.ec'
SECURITY=BASE+'NTRUPlus768CCASetupSecurity.ec'
RULES=(
 (GAME,'actual game initializes once and has no adversary phase before or inside KeyGen',r'module CCASharedSetupGame(E:KeygenExpand,A:CCAExtendedAdversary) = { proc run() : bool = { var pk:W8.t Array1152.t; var sk:W8.t Array2336.t; var win:bool; ROMInit.init(); RawXOFStreams.init(); CCADecapOracle.reset(); (pk,sk) <@ Keygen(UniformSeedRNG,E,SHAKEFROM).run(); win <@ CCAChallengeOriginal(A).run(pk,sk); return win; } }.'),
 (GAME,'programmed game changes only the expansion port',r'module CCAProgrammedFreshGame(A:CCAExtendedAdversary) = CCASharedSetupGame(ProgrammedFreshExpand,A).'),
 (GAME,'observer privately restores correlated E/F and executes the original challenge with the same key pair',r'module CCASetupObserver(A:CCAExtendedAdversary) = { proc guess(s:cca_setup_state) : bool = { var win:bool; ROG.init(); ROH.init(); RawXOFStreams.init(); CCADecapOracle.reset(); ROE.m <- s.`2; ROF.m <- s.`3; win <@ CCAChallengeOriginal(A).run(s.`1.`1.`kg_pk,s.`1.`1.`kg_sk); return win; } }.'),
 (GAME,'the original game projection preserves attacker and all shared oracle/raw/decapsulation states',r'lemma cca_setup_original_equiv (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) : equiv[CCAOriginalGame(A).run ~ CCASharedSetupGame(ExpandROM,A).run : ={glob A} ==> ={res,glob A,glob ROE,glob ROF,glob ROG,glob ROH,glob CCADecapOracle,glob RawXOFStreams}].'),
 (GAME,'actual ROM reification is concretely instantiated without a generic expansion exclusion',r'lemma cca_setup_game_reified_rom (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : Pr[CCASharedSetupGame(ExpandROM,A).run() @ &m:res]= Pr[CCASetupObserverDist.Sample(CCASetupObserver(A)).main( mk(fun z=>Pr[JointSetupSource(ExpandROM).guess(witness) @ &m:res=z])) @ &m:res].'),
 (GAME,'programmed reification uses its recorded joint state rather than the bare fresh output law',r'lemma cca_setup_game_reified_programmed (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : Pr[CCASharedSetupGame(ProgrammedFreshExpand,A).run() @ &m:res]= Pr[CCASetupObserverDist.Sample(CCASetupObserver(A)).main( mk(fun z=>Pr[JointSetupSource(ProgrammedFreshExpand).guess(witness) @ &m:res=z])) @ &m:res].'),
 (DIST,'the reified source law retains all output mass without normalization',r'lemma cca_setup_source_mu (E<:KeygenExpand) &m (event:cca_setup_state->bool) : Pr[JointSetupSource(E).guess(witness) @ &m:event res]= mu (mk(fun z=>Pr[JointSetupSource(E).guess(witness) @ &m:res=z])) event.'),
 (SECURITY,'joint-state distance is between actual and programmed subdistributions',r'lemma cca_setup_source_sdist &m qf qg : 0<=qf => 0<=qg => sdist (mk(fun z=>Pr[JointSetupSource(ExpandROM).guess(witness) @ &m:res=z])) (mk(fun z=>Pr[JointSetupSource(ProgrammedFreshExpand).guess(witness) @ &m:res=z])) <= proposal_delta 0 (qf+qg)+fresh_retry_tail qf qg.'),
 (SECURITY,'partial adversary distance has only the two finite-budget premises and explicit state exclusions',r'lemma cca_original_programmed_setup_distance (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m qf qg : 0<=qf => 0<=qg => `|Pr[CCAOriginalGame(A).run() @ &m:res]- Pr[CCAProgrammedFreshGame(A).run() @ &m:res]| <= proposal_delta 0 (qf+qg)+fresh_retry_tail qf qg.'),
 (SECURITY,'numeric endpoint is the original attacker game with no losslessness or freshness premise',r'lemma cca_original_programmed_setup_distance_239 (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : `|Pr[CCAOriginalGame(A).run() @ &m:res]- Pr[CCAProgrammedFreshGame(A).run() @ &m:res]| < 1%r/(2%r^239).'),
 (SECURITY,'the same stateful observer is passed to SDist contraction',r'have hc:=CCASetupObserverDist.adv_sdist (CCASetupObserver(A)) &m (mk(fun z=>Pr[JointSetupSource(ExpandROM).guess(witness) @ &m:res=z])) (mk(fun z=>Pr[JointSetupSource(ProgrammedFreshExpand).guess(witness) @ &m:res=z])).'),
)
MUTATIONS=(
 ('game-adds-adversary-queries-before-setup',GAME,'(pk,sk) <@ Keygen(UniformSeedRNG,E,SHAKEFROM).run();','win <@ CCAChallengeOriginal(A).run(witness,witness); (pk,sk) <@ Keygen(UniformSeedRNG,E,SHAKEFROM).run();'),
 ('game-replaces-unlimited-keygen-with-a-bounded-fallback',GAME,'(pk,sk) <@ Keygen(UniformSeedRNG,E,SHAKEFROM).run();','(pk,sk) <@ BoundedFallbackKeygen(E).run();'),
 ('programmed-game-discards-the-programmed-table',GAME,'CCASharedSetupGame(ProgrammedFreshExpand,A).','CCASharedSetupGame(FreshExpand,A).'),
 ('observer-erases-E-instead-of-restoring-setup-state',GAME,'ROE.m <- s.`2;','ROE.init();'),
 ('observer-erases-F-instead-of-restoring-setup-state',GAME,'ROF.m <- s.`3;','ROF.init();'),
 ('observer-resets-shared-tables-after-restoration',GAME,'ROE.m <- s.`2; ROF.m <- s.`3;','ROE.m <- s.`2; ROF.m <- s.`3; ROMInit.init();'),
 ('observer-replaces-the-actual-typed-raw-decap-continuation',GAME,'win <@ CCAChallengeOriginal(A).run(s.`1.`1.`kg_pk,s.`1.`1.`kg_sk);','win <@ StatelessChallenge(A).run(s.`1.`1.`kg_pk,s.`1.`1.`kg_sk);'),
 ('original-game-projection-forgets-raw-and-decapsulation-state',GAME,'={res,glob A,glob ROE,glob ROF,glob ROG,glob ROH,glob CCADecapOracle,glob RawXOFStreams}].','={res,glob A,glob ROE,glob ROF,glob ROG,glob ROH}].'),
 ('concrete-ROM-reification-assumes-adversary-termination',GAME,'lemma cca_setup_game_reified_rom (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m :','lemma cca_setup_game_reified_rom (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : islossless CCASetupObserver(A).guess =>'),
 ('concrete-programmed-reification-substitutes-bare-fresh-law',GAME,'lemma cca_setup_game_reified_programmed (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : Pr[CCASharedSetupGame(ProgrammedFreshExpand,A).run()','lemma cca_setup_game_reified_programmed (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : Pr[CCASharedSetupGame(FreshExpand,A).run()'),
 ('source-reification-conditions-on-setup-termination',DIST,'mu (mk(fun z=>Pr[JointSetupSource(E).guess(witness) @ &m:res=z])) event.','mu (dcond (mk(fun z=>Pr[JointSetupSource(E).guess(witness) @ &m:res=z])) predT) event.'),
 ('joint-distance-is-replaced-by-key-output-only-distance',SECURITY,'sdist (mk(fun z=>Pr[JointSetupSource(ExpandROM).guess(witness) @ &m:res=z])) (mk(fun z=>Pr[JointSetupSource(ProgrammedFreshExpand).guess(witness) @ &m:res=z]))','sdist (mk(fun z=>Pr[JointSetupSource(ExpandROM).guess(witness) @ &m:res.`1=z])) (mk(fun z=>Pr[JointSetupSource(ProgrammedFreshExpand).guess(witness) @ &m:res.`1=z]))'),
 ('attacker-termination-is-added-as-a-premise',SECURITY,'lemma cca_original_programmed_setup_distance (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m qf qg :','lemma cca_original_programmed_setup_distance (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m qf qg : islossless CCAProgrammedFreshGame(A).run =>'),
 ('final-attacker-binder-allows-direct-E-state-access',SECURITY,'lemma cca_original_programmed_setup_distance_239 (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams})','lemma cca_original_programmed_setup_distance_239 (A<:CCAExtendedAdversary {-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams})'),
 ('final-distance-assumes-actual-ROM-losslessness',SECURITY,'lemma cca_original_programmed_setup_distance_239 (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m :','lemma cca_original_programmed_setup_distance_239 (A<:CCAExtendedAdversary {-ROE,-ROF,-ROG,-ROH,-CCADecapOracle,-RawXOFStreams}) &m : islossless JointSetupSource(ExpandROM).guess =>'),
 ('contraction-uses-an-output-only-stateless-observer',SECURITY,'CCASetupObserverDist.adv_sdist (CCASetupObserver(A))','CCASetupObserverDist.adv_sdist (StatelessObserver(A))'),
)
